function decisionQueue(){return scopeAgents().filter(a=>a.status==='needs'&&!S().deferred.has(a.id));}
function decisionAgent(){return decisionQueue().find(a=>a.id===S().decision)||decisionQueue()[0];}
function renderDecisions(){
 const queue=decisionQueue(),a=decisionAgent(),deferred=scopeAgents().filter(w=>S().deferred.has(w.id));if(a)S().decision=a.id;
 return frame(3,`<section class="decision-layout"><aside class="decision-queue"><div class="decision-number">${queue.length.toString().padStart(2,'0')}<span>${tr('个决定，等你拍板','decisions await you')}</span></div><h3>${tr('今天的决策','Today’s decisions')}</h3>${queue.map((w,i)=>`<button class="decision-item ${w.id===a?.id?'selected':''}" data-decision="${w.id}"><span>0${i+1}</span><div><strong>${esc(l(w.title))}</strong><small>${w.agent} · ${projects[w.project].name}</small></div>${icon('arrow')}</button>`).join('')}<div class="deferred-info"><span>${tr('稍后处理','Deferred')} · ${deferred.length}</span>${deferred.map(w=>`<button class="deferred-item text-button" data-restore-decision="${w.id}">${icon('clock')}<span>${w.agent} · ${esc(l(w.title))}</span>${icon('arrow')}</button>`).join('')}${S().lastDeferred?button('undo-defer',tr('撤销刚才的稍后处理','Undo last deferral'),'undo','text-button'):''}</div>${button('new-command',t('newTask'),'plus','button')}</aside><main class="decision-paper">${S().decisionResult?`<div class="decision-result" data-testid="decision-result">${icon('check')}${esc(S().decisionResult)}</div>`:''}${a?`<header><span>${tr('给你的决策简报','YOUR DECISION BRIEF')}</span><span>0${queue.indexOf(a)+1} / 0${queue.length}</span></header><h2 data-testid="decision-title">${esc(l(a.title))}</h2><div class="paper-source">${av(a)}<span>${a.agent} · ${spaceName(a.space)} / ${projects[a.project].name}</span></div><section class="paper-context"><span>01</span><div><h3>${tr('发生了什么','What happened')}</h3><p>${esc(l(a.answer))}</p></div></section><section class="paper-recommend"><span>02</span><div><div class="paper-norma">${orb}<h3>${tr('Norma 建议这样推进','Norma’s recommendation')}</h3></div><p>${esc(l(a.recommendation)||l(a.summary))}</p><small>${tr('采用后只推进这项工作，不代替你执行最终合并或发布。','This advances the work; final merging and publishing remain separate.')}</small></div></section><div class="paper-evidence"><span>${tr('已完成的依据','Available evidence')}</span>${a.steps.map((s,i)=>`<span>${icon(i<a.progress?'check':'clock')}${esc(l(s))}</span>`).join('')}</div><footer><button class="button primary" data-action="accept-decision" data-testid="accept-decision">${icon('check')}${t(a.id==='navigation'?'review':'apply')}</button><button class="button" data-edit-decision="${a.id}">${t('modify')}</button><button class="text-button" data-action="defer-decision" data-testid="defer-decision">${t('defer')}${icon('clock')}</button></footer><button class="paper-original" data-chat="${a.id}">${t('sameSession')}<span>${tr('查看原对话','Open conversation')}${icon('out')}</span></button>`:`<div class="decision-empty">${icon('check')}<h2>${tr('暂时没有需要你拍板的事。','No decisions need you right now.')}</h2><p>${tr('执行中的 Agent 会继续推进，你可以安排下一件事。','Agents keep working. You can arrange the next goal.')}</p>${button('new-command',t('newTask'),'plus','button primary')}</div>`}</main><aside class="decision-watch"><span class="overline">${tr('其余工作，安静向前','THE REST KEEPS MOVING')}</span><h3>${tr('执行现场','In the field')}</h3>${scopeAgents().filter(w=>w.id!==a?.id).map(w=>rosterRow(w)).join('')}<div class="paper-footnote">${orb}<p>${tr('你决定方向。Norma 跟进每位 Agent，下一次只带着需要你解决的问题回来。','You set direction. Norma follows up with each agent and brings back decisions that need you.')}</p></div></aside></section>`);
}
